def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()


def block(text, needle):
    assert text.count(needle) == 1, ('non-unique extraction', needle)
    start = text.index(needle)
    first = text.index('{', start)
    depth = 0
    for pos in range(first, len(text)):
        depth += (text[pos] == '{') - (text[pos] == '}')
        if depth == 0:
            return text[start:pos + 1]
    raise AssertionError(('unclosed extraction', needle))


def unwrap_check_macros(text,name):
    needle=name+'!('
    while needle in text:
        start=text.index(needle);i=start+len(needle);depth=0;commas=[];quote=False;escape=False
        while i<len(text):
            ch=text[i]
            if quote:
                if escape:escape=False
                elif ch=='\\':escape=True
                elif ch=='"':quote=False
            elif ch=='"':quote=True
            elif ch in '([{':depth+=1
            elif ch in ')]}':
                if ch==')' and depth==0:break
                depth-=1
            elif ch==',' and depth==0:commas.append(i)
            i+=1
        assert i<len(text) and commas
        text=text[:start]+text[commas[-1]+1:i]+text[i+1:]
    return text

def extract(source):
    source=Path(source)
    candidate=(source/CUSTODY).read_bytes().decode('utf-8');state=(source/STATE).read_bytes().decode('utf-8')
    signing=(source/SIGNING).read_bytes().decode('utf-8');actor=(source/ACTOR).read_bytes().decode('utf-8')
    assert digest(candidate)==CANDIDATE_SHA256 and digest(state)==STATE_SHA256, 'actual custody/state byte drift'
    assert digest(signing)==SIGNING_SHA256 and digest(actor)==ACTOR_SHA256, 'actual dispatcher/diagnostics byte drift'
    ui=(source/UI).read_bytes().decode('utf-8');assert digest(ui)==UI_SHA256,'actual UI byte drift'
    prior_ui=ui
    for item in UI_RESTORATION:
        assert prior_ui.count(item['remove'])==1,'unique UI inverse absent'
        prior_ui=prior_ui.replace(item['remove'],item['restore'],1)
    assert digest(prior_ui)==UI_BASELINE_SHA256,'UI baseline inverse drift'
    restored={CUSTODY:candidate,SIGNING:signing}
    for item in reversed(P92_RESTORATION):
        assert restored[item['path']].count(item['after'])==1, 'unique P92 inverse absent'
        restored[item['path']]=restored[item['path']].replace(item['after'],item['before'],1)
    current_before=restored[CUSTODY];assert digest(current_before)==P91_CUSTODY_SHA256
    assert current_before.count(AFTER)==1 and BEFORE not in current_before
    legacy=current_before.replace(AFTER,BEFORE,1);assert digest(legacy)==BASELINE_SHA256
    impl=block(candidate,'impl SignedResultRecord {')
    candidate_check=block(impl,'    pub(super) fn check(&self)->Result<()>')
    kernel=block(impl,'    fn check_impl(')
    before_check=block(block(current_before,'impl SignedResultRecord {'),'    pub(super) fn check(&self)->Result<()>')
    expanded=unwrap_check_macros(unwrap_check_macros(kernel,'signed_result_check_at'),'signed_result_denied_at')
    expanded=expanded.replace('    fn check_impl(&self,#[cfg(wholepact_financial_rendered_host_semantic_ci)] mut capture:Option<&mut Option<SignedResultCheckFailure>>)->Result<()>','    pub(super) fn check(&self)->Result<()>',1)
    assert expanded==before_check, 'current production kernel differs from actual P91 check'
    legacy_check=block(block(legacy,'impl SignedResultRecord {'),'    pub(super) fn check(&self)->Result<()>')
    assert before_check.replace(AFTER,BEFORE,1)==legacy_check
    pre=candidate[candidate.index('// Only fatal restriction observers'):candidate.index('impl SignedResultRecord {')]
    observed=block(impl,'    pub(super) fn check_for_restriction(')
    dispatch=block(block(signing,'impl CGSlot {'),'    pub(super) fn observe_active(')
    prior_dispatch=block(block(restored[SIGNING],'impl CGSlot {'),'    pub(super) fn observe_active(')
    smacro=next(i['after'] for i in P92_RESTORATION if i['path']==SIGNING and i['before']=='')
    current_impl=block(candidate,'impl FinancialSignedResultCustodyV1 {');lease_impl=block(candidate,'impl SignedResultLease {')
    role_impl=block(ui,'impl RetainedFinancialRole {')
    ui_parts={name:block(role_impl,needle) for name,needle in [('current','    fn current(&self)'),('fatal','    fn current_for_restriction('),('kernel','    fn current_with_signed_check(')]}
    ui_parts['macro']=block(ui,'macro_rules! signed_result_fatal_check ')
    return dict(ui=ui,prior_ui=prior_ui,ui_parts=ui_parts,fatal_delegate=block(current_impl,'    pub(crate) fn check_current_for_fatal_observation('),candidate_source=candidate,legacy_source=legacy,current_before=current_before,candidate_check=candidate_check,kernel=kernel,before_check=before_check,legacy_check=legacy_check,pre=pre,observed=observed,dispatch=dispatch,prior_dispatch=prior_dispatch,dispatch_macro=smacro,actor=actor,
        current_method=block(current_impl,'    pub fn check_current('),retain_method=block(current_impl,'    pub(super) fn retain('),lease_check=block(lease_impl,'    pub(super) fn check('),
        helper=block(state,'pub(crate) fn observe_shared_wall('),actor_macro=block(state,'macro_rules! actor_boundary '))

def diagnostics_module(source):
    pieces={}
    def keep(name,text):pieces[name]=text;return text
    code='mod financial_ci_actor_diagnostics {\nuse super::*;use std::sync::atomic::{AtomicI32,AtomicU8};\n'
    code+=keep('codes',block(source,'macro_rules! codes '))+'\n'
    for name in ['DriverStage','ListenerStage','OriginStage','Class','PeerRole']:
        code+=keep(name,block(source,'codes!('+name+' {')+');')+'\n'
    for name in ['Detail','DriverDetail','OriginDetail','FailureFacts']:
        text=keep(name,block(source,'pub(crate) struct '+name+' '))
        text=re.sub(r'#\[serde\([^\n]*\)\]\s*','',text)
        code+='#[derive(Clone,Copy,Debug,PartialEq,Eq)] '+text+'\n'
    code+=keep('Slots',block(source,'struct Slots '))+'\nimpl Slots {\n'
    impl=block(source,'impl Slots {')
    for name,needle in [('new',' const fn new()'),('enter',' fn enter('),('active',' fn active('),('latch',' fn latch('),('latch_driver',' fn latch_driver('),('mark_failed',' fn mark_failed('),('failure',' fn failure(')]:code+=keep('slot_'+name,block(impl,needle))+'\n'
    code+='}\n'
    for name,needle in [('classify_io','pub fn classify_io('),('role_from_index','fn role_from_index('),('detail','fn detail('),('signed_result_driver_stage','fn signed_result_driver_stage('),('minimum_driver_stage','fn minimum_driver_stage('),('decode_driver','fn decode_driver('),('driver_detail','pub fn driver_detail('),('driver_minimum_detail','pub(crate) fn driver_minimum_detail('),('driver','pub fn driver('),('mark_failed','pub fn mark_failed('),('sample_failure','pub(crate) fn sample_failure(')]:code+=keep(name,block(source,needle))+'\n'
    code+='#[cfg(wholepact_financial_rendered_host_semantic_ci)]\n'+keep('fatal_helper',block(source,'pub fn check_signed_result_for_fatal_restriction('))+'\n'
    code+='static SLOTS:Slots=Slots::new();fn pid()->i32{11}\n'
    code+='pub(super) fn test_reset(role:PeerRole){SLOTS.pid.store(0,Ordering::Relaxed);SLOTS.enter(11,role);}pub(super) fn test_raw()->u32{SLOTS.driver.load(Ordering::Relaxed)}pub(super) fn test_decode(raw:u32,role:u8)->Option<DriverDetail>{decode_driver(raw,role)}pub(super) fn test_detail()->Option<DriverDetail>{decode_driver(test_raw(),SLOTS.role.load(Ordering::Relaxed))}pub(super) fn test_foreign_latch(stage:DriverStage){SLOTS.latch_driver(12,stage,Class::IoOther,1);}\n'
    code+='pub(super) fn origin(stage:OriginStage,_class:Class,_peer:Option<PeerRole>){note(stage);}pub(super) fn origin_io(stage:OriginStage,_error:&io::Error,_peer:Option<PeerRole>){note(stage);}fn note(stage:OriginStage){DIAGNOSTICS.with(|v|v.borrow_mut().push(match stage{OriginStage::SharedWallDeadline=>"SharedWallDeadline",OriginStage::SharedWallRollback=>"SharedWallRollback",OriginStage::SharedWallRead=>"SharedWallRead",_=>panic!("unexpected modeled origin")}));}\n}\n'
    return code,pieces

