def generate(source, out):
    source,out=Path(source),Path(out);value=extract(source)
    names=set(re.findall(r'#\[test\]\s*fn\s+([A-Za-z0-9_]+)',TESTS))
    extra=set(re.findall(r'#\[test\]\s*fn\s+([A-Za-z0-9_]+)',P92_TESTS))
    assert names==LEGACY_EXPECTED_TESTS and len(names)==17 and len(extra)==7 and set(re.findall(r'#\[test\]\s*fn\s+([A-Za-z0-9_]+)',UI_TESTS))==UI_EXPECTED_TESTS and len(UI_EXPECTED_TESTS)==3 and names|extra|UI_EXPECTED_TESTS==EXPECTED_TESTS, 'test selection drift'
    diagnostics,pieces=diagnostics_module(value['actor'])
    prefix=PREFIX.replace('__ACTUAL_DRIVER_DIAGNOSTICS__',diagnostics)
    legacy=value['legacy_check'].replace('fn check(','fn check_legacy(',1)
    before=value['before_check'].replace('fn check(','fn check_before_p92(',1)
    rust=prefix.replace('#![allow(dead_code)]','#![allow(dead_code)]\nextern crate self as wholepact_financial_coordinator_origin;',1)+'\n'+value['actor_macro']+'\nmod state {use super::*;\n'
    rust+='pub(super) fn wall_ms()->Result<u64>{log("wall");SAMPLES.with(|v|v.set(v.get()+1));WALL.with(|v|{let mut callback=v.borrow_mut();match callback.as_mut(){Some(f)=>f(),None=>Ok(100)}})}\n'+value['helper']+'\n}\n'
    rust+='mod custody {use super::*;\n'+value['pre']+'\nimpl SignedResultRecord {\n'+value['candidate_check']+'\n'+value['kernel']+'\n#[cfg(wholepact_financial_rendered_host_semantic_ci)]\n'+value['observed']+'\n'+legacy+'\n'+before+'\npub(super) fn check_candidate(&self)->Result<()>{self.check()}\n}\n'
    rust+='impl FinancialSignedResultCustodyV1 {\n'+value['current_method']+'\n#[cfg(wholepact_financial_rendered_host_semantic_ci)]\n'+value['fatal_delegate']+'\n'+value['retain_method']+'\n}\nimpl SignedResultLease {\n'+value['lease_check']+'\n}\n'
    rust+=value['dispatch_macro']+'\nconst G_SETUP_REVIEW:u8=1;const G_SETUP_ADMITTED:u8=2;const G_REVIEW:u8=3;const G_SERVING:u8=4;\nimpl CGSlot {\n'+value['dispatch']+'\n}\n}\n'+value['ui_parts']['macro']+'\nimpl RetainedFinancialRole {\n'+'\n'.join(value['ui_parts'][key] for key in ['current','fatal','kernel'])+'\n}\n'+TESTS+'\n'+P92_TESTS+'\n'+UI_TESTS
    out.mkdir(parents=True,exist_ok=True);(out/'retired-wall-trace.rs').write_text(rust)
    binding={'source':str(source),'files':{CUSTODY:CANDIDATE_SHA256,STATE:STATE_SHA256,SIGNING:SIGNING_SHA256,ACTOR:ACTOR_SHA256,UI:UI_SHA256},'legacy_full_source_sha256':BASELINE_SHA256,'p91_full_source_sha256':P91_CUSTODY_SHA256,'candidate_check_sha256':digest(value['candidate_check']),'current_kernel_sha256':digest(value['kernel']),'current_observed_sha256':digest(value['observed']),'current_dispatch_sha256':digest(value['dispatch']),'legacy_check_sha256':digest(value['legacy_check']),'unchanged_helper_sha256':digest(value['helper']),'unchanged_actor_macro_sha256':digest(value['actor_macro']),'actual_driver_pieces_sha256':{k:digest(v) for k,v in pieces.items()},'rust_sha256':digest(rust),'test_count':len(EXPECTED_TESTS),'legacy_test_count':17,'new_test_count':10,'ui_test_count':3,'actual_ui_pieces_sha256':{k:digest(v) for k,v in value['ui_parts'].items()},'actual_custody_fatal_delegate_sha256':digest(value['fatal_delegate']),'ui_baseline_inverse_sha256':UI_BASELINE_SHA256,'tests':sorted(EXPECTED_TESTS),'generated':True,'executed':False,'production_kernel_macro_inverse':True,'limits':'Actual current public/observed/kernel, CGSlot dispatch, bound helper and driver slots. Literal UI role methods/macro and cross-crate delegates; modeled return tokens, monotonic/wall clocks, entry/Core/request carriers and origin sinks; no whole Window/revoke runtime simulation; no native liveness/authority or initiating cause proof. Existing17 tests retain exact bodies and execute actual current wrapper/kernel, not a restored candidate.','diagnostic_effect':'Only phase6 and explicitly fatal UI check callers capture finite first local returned operation; ordinary custody/current/retain/lease paths do not publish new driver details. minimum_bounds identifies tied immutable minimum inputs, not every expired input.'}
    (out/'binding.json').write_text(json.dumps(binding,indent=2,sort_keys=True)+'\n');return binding

def run(command, path, timeout):
    try:
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                text=True, timeout=timeout)
    except subprocess.TimeoutExpired as error:
        partial = error.stdout or ''
        path.write_text(partial.decode(errors='replace') if isinstance(partial, bytes) else partial)
        raise
    except OSError as error:
        path.write_text(str(error) + '\n')
        raise
    path.write_text(result.stdout)
    if result.returncode:
        print(result.stdout[-16384:], file=sys.stderr)
        raise SystemExit(f'{path.name} failed: {result.returncode}')
    return result.stdout


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, required=True)
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('--run', action='store_true', help='Explicitly compile/run only in an authorized test environment')
    args = parser.parse_args()
    binding = generate(args.source, args.out)
    print(json.dumps({'generated': True, 'executed': False, 'tests': binding['test_count']}))
    if args.run:
        # Never merge stale successful execution evidence into a fresh attempt.
        execution = args.out / 'execution'
        execution.mkdir(exist_ok=False)
        receipt = {'status': 'running', 'native_execution_attempted': False,
                   'native_listings_completed': [], 'compiler': None,
                   'expected_compiler': PINNED_RUSTC, 'compiled_profiles': [],
                   'tests_started': [], 'profiles_passed': [],
                   'tests_per_profile': len(EXPECTED_TESTS),
                   'rust_sha256': binding['rust_sha256'],
                   'generator_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
                   'binding_sha256': hashlib.sha256((args.out / 'binding.json').read_bytes()).hexdigest()}

        def retain():
            receipt['log_sha256'] = {path.name: hashlib.sha256(path.read_bytes()).hexdigest()
                                     for path in sorted(execution.glob('*.log'))}
            (execution / 'receipt.json').write_text(json.dumps(receipt, indent=2, sort_keys=True) + '\n')

        retain()
        try:
            version = run(['rustc', '--version'], execution / 'compiler-version.log', 15).strip()
            receipt['compiler'] = version
            if version != PINNED_RUSTC:
                raise RuntimeError('wrong rustc identity: ' + version)
            for profile, flags in [('production', []), ('semantic', ['--cfg', 'wholepact_financial_rendered_host_semantic_ci'])]:
                binary = execution / ('retired-wall-tests-' + profile)
                run(['rustc', '--edition=2021', '--test', *flags, str(args.out / 'retired-wall-trace.rs'), '-o', str(binary)], execution / (profile + '-compile.log'), 60)
                receipt['compiled_profiles'].append(profile)
                retain()
                receipt['native_execution_attempted'] = True
                retain()
                listed = run([str(binary), '--list'], execution / (profile + '-list.log'), 10)
                receipt['native_listings_completed'].append(profile)
                names = {line[:-6] for line in listed.splitlines() if line.endswith(': test')}
                assert names == EXPECTED_TESTS, ('compiled test inventory mismatch', names)
                receipt['tests_started'].append(profile)
                retain()
                output = run([str(binary), '--test-threads=1'], execution / (profile + '-tests.log'), 30)
                assert f'{len(EXPECTED_TESTS)} passed; 0 failed; 0 ignored' in output
                receipt['profiles_passed'].append(profile)
                retain()
            receipt.update(status='success')
            retain()
        except BaseException as error:
            receipt.update(status='timed_out' if isinstance(error, subprocess.TimeoutExpired) else 'failed',
                           error_type=type(error).__name__)
            retain()
            raise
        print(json.dumps({'executed': True, 'profiles': receipt['profiles_passed'], 'tests_per_profile': len(EXPECTED_TESTS)}))


if __name__ == '__main__':
    main()
